import{_ as t,c as s,o as a,ag as i}from"./chunks/framework.Ci10AEOF.js";const r="/docs-website/assets/users.Bvh85vZW.png",g=JSON.parse('{"title":"User Management","description":"Users, roles, and authentication","frontmatter":{"title":"User Management","description":"Users, roles, and authentication"},"headers":[],"relativePath":"engine/user_management.md","filePath":"engine/user_management.md","lastUpdated":1793057853000}'),n={name:"engine/user_management.md"};function o(d,e,l,h,c,p){return a(),s("div",null,e[0]||(e[0]=[i('<h1 id="user-management" tabindex="-1">User Management <a class="header-anchor" href="#user-management" aria-label="Permalink to &quot;User Management&quot;">​</a></h1><p>OIE maintains its own user accounts for anyone who needs to log in, whether through either administrator, the Command Line Interface, or the REST API. The Users view lets you create, edit, and remove these accounts. Role-based access control is available as a <a href="https://openintegrationengine.org/plugins/" target="_blank" rel="noreferrer">community extension</a> for restricting specific operations to designated user roles.</p><p>A password, including the admin account&#39;s, is reset in the Edit User dialog with <strong>New Password</strong> and <strong>Confirm New Password</strong>, or from the <a href="./command_line_interface.html">Command Line Interface</a> with <code>user changepw</code>. The CLI logs in first, and its shipped config file contains <code>user=admin</code> and <code>password=admin</code>, which do not match the admin password a new database generates (see <a href="./command_line_interface.html#configuration">Configuration</a>).</p><h2 id="default-account" tabindex="-1">Default account <a class="header-anchor" href="#default-account" aria-label="Permalink to &quot;Default account&quot;">​</a></h2><p>A new database starts with one account, <code>admin</code>. <a href="./accessing_the_administrator.html#initial-admin-password">Initial admin password</a> covers how it gets its first password. A database that already exists keeps its accounts and passwords.</p><h2 id="users-view" tabindex="-1">Users view <a class="header-anchor" href="#users-view" aria-label="Permalink to &quot;Users view&quot;">​</a></h2><p>Open the Users view by clicking <strong>Users</strong> in the main navigation panel. The table displays all user accounts on the server.</p><p><img src="'+r+`" alt="The Users view listing two user accounts"></p><h3 id="users-table-columns" tabindex="-1">Users table columns <a class="header-anchor" href="#users-table-columns" aria-label="Permalink to &quot;Users table columns&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Username</strong></td><td>The login name (must be unique)</td></tr><tr><td><strong>First Name</strong></td><td>The user&#39;s given name</td></tr><tr><td><strong>Last Name</strong></td><td>The user&#39;s family name</td></tr><tr><td><strong>Email</strong></td><td>The user&#39;s email address. This is the address used when an alert sends notifications to this user.</td></tr><tr><td><strong>Country</strong></td><td>Country of residence</td></tr><tr><td><strong>State/Territory</strong></td><td>State or territory (for users in the United States)</td></tr><tr><td><strong>Phone Number</strong></td><td>Contact phone number</td></tr><tr><td><strong>Organization</strong></td><td>The user&#39;s organization or company</td></tr><tr><td><strong>Role</strong></td><td>Their role within the organization (e.g. Employee - Engineer, Independent Contractor)</td></tr><tr><td><strong>Business</strong></td><td>The industry or field they work in (e.g. HIE, Hospital, Lab)</td></tr><tr><td><strong>Last Login</strong></td><td>Date and time of the most recent successful login. A REST API request authenticated with HTTP Basic does not update it</td></tr><tr><td><strong>Description</strong></td><td>An optional free-text description or notes field</td></tr></tbody></table><h2 id="managing-user-accounts" tabindex="-1">Managing user accounts <a class="header-anchor" href="#managing-user-accounts" aria-label="Permalink to &quot;Managing user accounts&quot;">​</a></h2><h3 id="creating-a-new-user" tabindex="-1">Creating a new user <a class="header-anchor" href="#creating-a-new-user" aria-label="Permalink to &quot;Creating a new user&quot;">​</a></h3><ol><li>Click <strong>New User</strong> in the task panel</li><li>Fill in the required fields (marked with a red asterisk): <ul><li><strong>Username</strong></li><li><strong>New Password</strong></li><li><strong>Confirm New Password</strong></li></ul></li><li>Optionally fill in the remaining profile fields: First Name, Last Name, Email, Country, State/Territory, Phone, Organization, Role, Business, Description</li><li>Click <strong>Finish</strong></li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Both password fields must match exactly. The username must not already exist in the system.</p></div><h3 id="editing-a-user" tabindex="-1">Editing a user <a class="header-anchor" href="#editing-a-user" aria-label="Permalink to &quot;Editing a user&quot;">​</a></h3><ol><li>Select the user in the table</li><li>Click <strong>Edit User</strong> in the task panel (or double-click the user row)</li><li>Modify any fields as needed. The Username field is editable, but the new name must be unique</li><li>Click <strong>Finish</strong></li></ol><h3 id="deleting-a-user" tabindex="-1">Deleting a user <a class="header-anchor" href="#deleting-a-user" aria-label="Permalink to &quot;Deleting a user&quot;">​</a></h3><ol><li>Select the user in the table</li><li>Click <strong>Delete User</strong> in the task panel</li><li>Confirm the deletion when prompted</li></ol><h3 id="user-tasks-summary" tabindex="-1">User tasks summary <a class="header-anchor" href="#user-tasks-summary" aria-label="Permalink to &quot;User tasks summary&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Task</th><th>Description</th></tr></thead><tbody><tr><td><strong>Refresh</strong></td><td>Reload the users table</td></tr><tr><td><strong>New User</strong></td><td>Open the new user dialog</td></tr><tr><td><strong>Edit User</strong></td><td>Open the selected user for editing</td></tr><tr><td><strong>Delete User</strong></td><td>Remove the selected user from the server</td></tr></tbody></table><h2 id="password-policy" tabindex="-1">Password policy <a class="header-anchor" href="#password-policy" aria-label="Permalink to &quot;Password policy&quot;">​</a></h2><p>Password requirements are controlled through properties in <code>conf/mirth.properties</code>. The shipped file sets <code>password.minlength = 15</code>, <code>password.retrylimit = 100</code> and <code>password.lockoutperiod = 1</code>, so a password needs at least 15 characters and lockout is on: the 101st consecutive failed login locks the account for an hour. Every other key ships at <code>0</code>, which turns its check off, and a key missing from the file is read as <code>0</code>. The server reads these properties once, when it starts, so a change takes effect at the next restart.</p><table tabindex="0"><thead><tr><th>Property</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>password.minlength</code></td><td>Minimum number of characters</td><td><code>15</code></td></tr><tr><td><code>password.minupper</code></td><td>Minimum uppercase letters (-1 = none allowed)</td><td><code>0</code></td></tr><tr><td><code>password.minlower</code></td><td>Minimum lowercase letters (-1 = none allowed)</td><td><code>0</code></td></tr><tr><td><code>password.minnumeric</code></td><td>Minimum digits (-1 = none allowed)</td><td><code>0</code></td></tr><tr><td><code>password.minspecial</code></td><td>Minimum special characters (-1 = none allowed)</td><td><code>0</code></td></tr><tr><td><code>password.retrylimit</code></td><td>Consecutive failed logins allowed before the account locks. With <code>5</code> the sixth failure locks it (0 = no lockout)</td><td><code>100</code></td></tr><tr><td><code>password.lockoutperiod</code></td><td>Hours the account stays locked. The failure count is also cleared once this many hours pass after the last failed login. With <code>0</code> the account never locks, whatever <code>password.retrylimit</code> says</td><td><code>1</code></td></tr><tr><td><code>password.expiration</code></td><td>Days until the password expires (0 = never)</td><td><code>0</code></td></tr><tr><td><code>password.graceperiod</code></td><td>Days the user can still log in after the password expires, counted from the first login after expiry. Each of those logins asks for a new password (0 = unlimited, -1 = no grace, the login is refused)</td><td><code>0</code></td></tr><tr><td><code>password.reuseperiod</code></td><td>A password set within this many days cannot be set again (0 = no limit, -1 = never again)</td><td><code>0</code></td></tr><tr><td><code>password.reuselimit</code></td><td>Times a password already in the user&#39;s history may be set again (0 = no limit, -1 = never again)</td><td><code>0</code></td></tr></tbody></table><p>A special character is one of <code>! &quot; # $ % &amp; &#39; ( ) * + , / : ; &lt; = &gt; ? @ [ ] ^ _ \` ~</code>. A space, hyphen, period, backslash, <code>{</code>, <code>|</code>, and <code>}</code> do not count.</p><h3 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h3><p>The password requirements section of <code>conf/mirth.properties</code> with a policy set:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.minlength</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 15</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.minupper</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.minlower</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.minnumeric</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.minspecial</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.retrylimit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 5</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.lockoutperiod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.expiration</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 90</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.graceperiod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 7</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.reuseperiod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.reuselimit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = -1</span></span></code></pre></div><p>With these values a new password needs at least 15 characters including an uppercase letter, a lowercase letter, a digit, and a special character, and any password in the user&#39;s history is rejected with &quot;You cannot reuse the same password.&quot; While both reuse keys are <code>0</code>, as shipped, each password change clears the older history, so the history starts with the password in place when this policy takes effect. The sixth consecutive failed login locks the account for an hour; while it is locked, a login is refused before the password is checked and the message says how long remains. The password expires 90 days after it was set. For seven days from the first login after that, the login still succeeds and the user is asked to change the password. After that the login is refused until an administrator sets a new password, for example with <code>user changepw</code>.</p><h2 id="first-login" tabindex="-1">First login <a class="header-anchor" href="#first-login" aria-label="Permalink to &quot;First login&quot;">​</a></h2><p>The first time each user logs in, the Administrator opens a welcome dialog that asks for a new password, which must meet the <a href="#password-policy">password policy</a>, and for the user&#39;s account details. <a href="./accessing_the_administrator.html#first-login">First login</a> walks through it.</p><h2 id="username-behavior" tabindex="-1">Username behavior <a class="header-anchor" href="#username-behavior" aria-label="Permalink to &quot;Username behavior&quot;">​</a></h2><p>Usernames are case-insensitive by default: <code>Admin</code>, <code>admin</code>, and <code>ADMIN</code> all refer to the same account.</p>`,32)]))}const m=t(n,[["render",o]]);export{g as __pageData,m as default};
